package com.github.axodenelcorvus.model.entry;


import java.util.Objects;

//Does not include primary key that is expected to be autogenerated by database
public final class PokemonSpriteEntry implements SqlTupleSerializable {

    private final int pokemonId;
    private final String spriteFormDescriptor;
    private final String staticImgResourcePath;

    public PokemonSpriteEntry(int nationalDexId, String singleAltSpriteFormDescriptor) {
        this.pokemonId = nationalDexId;
        this.spriteFormDescriptor = singleAltSpriteFormDescriptor;

        staticImgResourcePath = "/universal_default/%d_alt_form.png"
                                                .formatted(nationalDexId);
    }

    public PokemonSpriteEntry(int pokemonId, GenderSpriteForm genderForm, RegionalForm region, int nationalDexId) {
        //Default static image resource path takes this shape, along with .png extension added later
        String[] staticImgRsrcPathSegments = { "universal_default", String.valueOf(nationalDexId) };
        StringBuilder pathStrBuilder = new StringBuilder();

        //BUILD 1st PART OF DESCRIPTOR AND STATIC IMAGE RESOURCE PATH
        String formDescriptor = findGenderDescriptor(genderForm);
        if (genderForm == GenderSpriteForm.FEMALE)
            staticImgRsrcPathSegments[0] = "female";
        
        //BUILD 2nd PART OF DESCRIPTOR AND STATIC IMAGE RESOURCE PATH (as needed)
        if (region != RegionalForm.STANDARD) {
            var regionName = region.getRegionName();
            formDescriptor = "%s %c%s".formatted(
                    formDescriptor,
                    Character.toUpperCase(regionName.charAt(0)),
                    regionName.substring(1)
            );

            staticImgRsrcPathSegments[1] += '_' + regionName;
        }

        //BUILD OUTER SEGMENTS TO FORM COMPLETE PATH TO STATIC IMAGE RESOURCE PATH
        String completeStaticImgResourcePath = pathStrBuilder
                                .append('/')
                                .append(staticImgRsrcPathSegments[0])
                                .append('/')
                                .append(staticImgRsrcPathSegments[1])
                                .append(".png")
                                .toString();

        this.pokemonId = pokemonId;
        staticImgResourcePath = completeStaticImgResourcePath;
        spriteFormDescriptor = formDescriptor;
    }

    private String findGenderDescriptor(GenderSpriteForm genderForm) {
        return switch (genderForm) {
            case GenderSpriteForm.MALE ->   "Male";
            case GenderSpriteForm.FEMALE -> "Female";
            case GenderSpriteForm.NONE ->   "Default";
        };
    }

    public int getForeignKey() {
        return pokemonId;
    }

    public String getSpriteFormDescriptor() {
        return spriteFormDescriptor;
    }

    public String getStaticImgResourcePath() {
        return staticImgResourcePath;
    }


    public static String TABLE_NAME = "significant_sprite_forms";
    public static String COLUMN_LIST = "(pokemon_id, name, static_img_resource_path)";

    @Override
    public String toSqlTuple(SqlStringResolver sqlStrResolution) {
        return  "(%d, %s, %s)".formatted(
                pokemonId,
                sqlStrResolution.apply(spriteFormDescriptor),
                sqlStrResolution.apply(staticImgResourcePath)
        );
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof PokemonSpriteEntry other
                && pokemonId == other.pokemonId
                //Will use equals here since not possible for either of these fields to be nullified
                && spriteFormDescriptor.equals(other.spriteFormDescriptor)
                && staticImgResourcePath.equals(other.staticImgResourcePath);
    }

    @Override
    public int hashCode() {
        //Composite of Pokemon's national Dex ID (found among file name) and their pokemonId (a foreign key referencing)
        //referencing entries in pokemon table can be used to identify distinct entires/records
        return Objects.hash(pokemonId, staticImgResourcePath);
    }

    @Override
    public String toString() {
        return "pokemonId={" + pokemonId +
                ", spriteFormDescriptor=\"" + spriteFormDescriptor + '\"' +
                ", staticImgResourcePath=\"" + staticImgResourcePath + '\"' +
                '}';
    }
}
